from lib import *
S = SS('v64')
steps = [
    step("头部采样。3000 个 trace(49 个出错、95 个慢、2856 个正常),在 trace 的第一个 span 上按 trace id 做决定。100%:保留 3000 个 trace、12000 个 span。10%:保留 271 个 trace、1084 个 span,其中出错的 trace 保留 11 / 49,慢 trace 保留 6 / 95,正常 trace 保留 254 / 2856。1%:保留 31 个 trace、124 个 span,出错的 0 / 49,慢 trace 0 / 95,正常 31 / 2856。头部采样做决定的时候还不知道这个 trace 之后会不会出错、会不会变慢,所以出错和慢的 trace 同样被丢掉。", t=tl(S(1)), mark=lidx(S(1), '10%  ', '1%  '), done=lidx(S(1), '100%'), b=bars([['100%:出错的保留', 49, '49 / 49'], ['10%:出错的保留', 11, '11 / 49'], ['1%:出错的保留', 0, '0 / 49'], ['1%:慢 trace 保留', 0, '0 / 95']], 49, done=[0], mark=[1, 2, 3]), kv=KV([['10% 头部采样', '保留 271 个 trace,出错的只留 11 / 49'], ['1% 头部采样', '保留 31 个 trace,出错和慢的都是 0']], ['1% 头部采样'])),
    step("多个服务的采样决定要一致。A → B → C 三个服务各有自己的 TracerProvider,每种 3000 个请求。(a)A 按 10% 决定,B、C 跟随父 span 的采样标志:291 个 trace 有 span,291 个三个 span 都在,没有残缺的。(b)三个服务不看父 span、各自独立,A 10%、B 50%、C 100%:3000 个 trace 都有 span,其中完整的只有 308 个,收到 2 个 span 的 1173 个,只收到 1 个 span 的 1519 个。(c)三个服务都不看父 span、同一个比例 10%:308 个,全部三个 span 都在,没有残缺的(因为 TraceIdRatioBased 按 trace id 确定性地决定)。", t=tl(S(2)), mark=lidx(S(2), '(b)各自独立'), done=lidx(S(2), '(a)A 按', '(c)各自独立'), b=bars([['(a)只收到 1~2 个 span 的 trace', 0, '0'], ['(b)收到 3 个 span 的 trace', 308, '308'], ['(b)只收到 1 个 span 的 trace', 1519, '1519'], ['(b)收到 2 个 span 的 trace', 1173, '1173']], 1519, done=[0], mark=[1, 2, 3]), kv=KV([['跟随父 span', '291 个 trace 全部完整'], ['不同比例各自独立', '308 完整,1173 收到 2 个,1519 只收到 1 个'], ['同一个比例各自独立', '308 个全部完整,因为按 trace id 确定性决定']], ['不同比例各自独立'])),
    step("尾部采样(OpenTelemetry Collector 的 tail_sampling,decision_wait 3 s):出错的全留、耗时超过 500 ms 的全留、其余按 5% 留。应用把 3000 个 trace 全部发给 Collector:保留 288 个 trace(全量是 3000 个),出错的 49 / 49,慢 trace 95 / 95,正常 trace 144 / 2856(5% 的目标约 142 个),保留下来的 288 个 trace 都是 4 个 span 完整的。file exporter 的输出文件 399,817 字节,全量是 2,761,015 字节。从应用 flush 完到第一次有采样输出用了 3.2 s,Collector 内存(RSS)185 MB。", t=tl(S(3)), mark=lidx(S(3), 'file exporter', '应用生成'), done=lidx(S(3), '出错的 trace', '慢 trace', '正常 trace', '保留的 trace 数'), b=bars([['出错的 trace 保留', 49, '49 / 49'], ['慢 trace 保留', 95, '95 / 95'], ['保留的 trace 数', 288, '288 / 3000'], ['保留下来的文件大小(KB)', 399.8, '399,817 字节(全量 2,761,015)']], 400, done=[0, 1], mark=[2, 3]), kv=KV([['出错和慢的 trace', '全部保留'], ['正常 trace', '144 / 2856(约 5%)'], ['输出文件', '399,817 字节,全量 2,761,015 字节'], ['代价', '等 3 s 才有输出,Collector 内存 185 MB']], ['出错和慢的 trace'])),
    step("迟到的 span。同样的配置(decision_wait 2 s),100 个出错的 trace,出错的那个 span 比其他 span 晚发出。晚 0.5 s:100 个 trace 全部保留,含出错 span 的 100 个,4 个 span 都在的 100 个。晚 4.0 s(比 decision_wait 还晚):只保留了 5 个,也就是约 5% 的概率保留——决定的时候这个 trace 里还没有错误 span,它被当成了普通 trace。", t=tl(S(4)), mark=lidx(S(4), '4.0 s'), done=lidx(S(4), '0.5 s'), b=bars([['晚 0.5 s:保留', 100, '100 / 100'], ['晚 4.0 s:保留', 5, '5 / 100']], 100, done=[0], mark=[1]), kv=KV([['出错 span 晚 0.5 s', '100 / 100 保留'], ['出错 span 晚 4.0 s(> decision_wait)', '只保留 5 / 100'], ['原因', '决定时 trace 里还没有错误 span']], ['出错 span 晚 4.0 s(> decision_wait)'])),
]
